#ifndef RING_BUFFER_HPP
#define RING_BUFFER_HPP

#include <cstddef>
#include <string>
#include <vector>

/* One logged event: when it happened, and what happened. */
struct Event {
    long long at = 0;      /* a timestamp; it is NOT always increasing */
    std::string text;      /* one word, no spaces */
};

/* A bounded first-in, first-out buffer of events.
 *
 * The PUBLIC part is the contract. main.cpp is written against exactly
 * these names and signatures, so changing one stops it compiling.
 *
 * Everything under `private:` is yours. The three members below are
 * what a ring buffer usually needs — a block of slots, where the
 * oldest one is, and how many are in use — and you may replace them
 * with anything that behaves the same.
 */
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity);

    std::size_t capacity() const;
    std::size_t size() const;
    bool empty() const;
    bool full() const;

    /* Adds `e` as the newest event. Returns false, and changes nothing
     * at all, when there is no room. */
    bool push(const Event& e);

    /* Removes the OLDEST event into `out`. Returns false when there is
     * nothing to remove, and leaves `out` alone. */
    bool pop(Event& out);

    /* The i-th oldest event still held. i < size(). */
    Event at(std::size_t i) const;

private:
    std::size_t cap_;
    std::size_t start_ = 0;
    std::size_t count_ = 0;
    std::vector<Event> slots_;
};

#endif

#include "ring_buffer.hpp"

RingBuffer::RingBuffer(std::size_t capacity)
    : cap_(capacity), slots_(capacity) {}

std::size_t RingBuffer::capacity() const {
    return cap_;
}

std::size_t RingBuffer::size() const {
    return count_;
}

bool RingBuffer::empty() const {
    return count_ == 0;
}

bool RingBuffer::full() const {
    return count_ == cap_;
}

bool RingBuffer::push(const Event& e) {
    if (full()) return false;
    slots_[(start_ + count_) % cap_] = e;
    ++count_;
    return true;
}

bool RingBuffer::pop(Event& out) {
    if (empty()) return false;
    out = slots_[start_];
    start_ = (start_ + 1) % cap_;
    --count_;
    return true;
}

Event RingBuffer::at(std::size_t i) const {
    return slots_[(start_ + i) % cap_];
}

/* GIVEN, and read-only for this milestone.
 *
 * The driver: it reads commands from stdin, calls the buffer, and
 * prints what came back. It is the thing your ring_buffer.cpp has to
 * satisfy, which is why you cannot edit it here — a test you can edit
 * is not a test.
 */
#include <iostream>
#include <sstream>
#include <string>

#include "ring_buffer.hpp"

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::size_t cap = 0;
    if (!(std::cin >> cap)) return 0;
    RingBuffer buf(cap);

    std::string line;
    std::getline(std::cin, line);          /* the rest of the capacity line */

    while (std::getline(std::cin, line)) {
        std::istringstream in(line);
        std::string cmd;
        if (!(in >> cmd)) continue;

        if (cmd == "push") {
            Event e;
            if (!(in >> e.at >> e.text)) continue;
            if (!buf.push(e)) std::cout << "full\n";
        } else if (cmd == "pop") {
            Event e;
            if (buf.pop(e)) std::cout << e.at << ' ' << e.text << '\n';
            else std::cout << "empty\n";
        } else if (cmd == "size") {
            std::cout << buf.size() << '/' << buf.capacity() << '\n';
        } else if (cmd == "dump") {
            if (buf.empty()) {
                std::cout << "(none)\n";
            } else {
                for (std::size_t i = 0; i < buf.size(); ++i) {
                    const Event e = buf.at(i);
                    std::cout << e.at << ' ' << e.text << '\n';
                }
            }
        }
    }
    return 0;
}
